static const char cr2_web_html[] = "<!doctype html>\n<html lang=\"en\">\n<head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#172e29\"><title>Speaker \u00b7 C-R2</title><link rel=\"stylesheet\" href=\"/control.css\"><script src=\"/control.js\" defer></script></head>\n<body><main>\n<header><a class=\"brand\" href=\"/control\"><span class=\"mark\" aria-hidden=\"true\">\u25c9</span> SPEAKER <span>C-R2</span></a><span id=\"connection\" class=\"pill\">Connecting</span></header>\n<section class=\"hero\"><p class=\"eyebrow\">YOUR SOUND, WITHIN REACH</p><h1>A little more<br>room for music.</h1><p class=\"intro\">Volume and power, straight from your speaker.</p></section>\n<section class=\"player\" aria-label=\"Speaker controls\">\n<div class=\"player-top\"><div><p class=\"eyebrow\">AMPLIFIER</p><h2 id=\"state\">Connecting\u2026</h2><p id=\"detail\">Reading the speaker</p></div><button id=\"power\" class=\"power\" disabled>Turn on</button></div>\n<div class=\"music\"><div><p class=\"eyebrow\">SPOTIFY</p><strong id=\"track\">Choose your music</strong><p id=\"artist\">Connecting to the laptop</p></div><button id=\"play\" disabled>Play</button></div>\n<div class=\"volume-head\"><label for=\"volume\">Volume</label><output id=\"level\" for=\"volume\">40</output></div>\n<input type=\"range\" id=\"volume\" min=\"0\" max=\"100\" value=\"40\" step=\"1\" disabled aria-describedby=\"volume-help\">\n<div class=\"scale\"><span>Quiet</span><span>Full range</span></div>\n<div class=\"controls\"><button id=\"down\" disabled aria-label=\"Lower volume by five\">\u2212</button><button id=\"mute\" disabled>Mute</button><button id=\"up\" disabled aria-label=\"Raise volume by five\">+</button></div>\n<p id=\"volume-help\" class=\"hint\">Starts at a quiet level. Increase gradually.</p>\n<div id=\"message\" class=\"message\" role=\"status\" aria-live=\"polite\"></div>\n</section>\n<section class=\"metrics\" aria-label=\"Live status\">\n<article><p>POWER SOURCE</p><strong id=\"source\">\u2014</strong><span id=\"rail\">Waiting for readings</span><span id=\"allowance\"></span></article>\n<article><p>BATTERY</p><strong id=\"battery\">\u2014</strong><span id=\"charging\">Charging disabled</span></article>\n<article><p>WI-FI</p><strong id=\"wifi\">\u2014</strong><span id=\"signal\">Connecting</span></article>\n</section>\n<div class=\"notes\"><p><strong>Play starts the music and wakes the speaker quietly.</strong> It resumes this receiver\u2019s Spotify track, or starts \u201cLose Control\u201d when no track is selected. To choose other music, select <strong>Speaker C-R2 Snapcast</strong> in Spotify. Keep the laptop\u2019s music server running.</p><p><strong>Standby keeps Wi-Fi available.</strong> Keep this page open while listening. The amplifier returns to standby within 90 seconds if its controller disconnects.</p></div>\n<details><summary>Connection &amp; device details</summary><dl><dt>Firmware</dt><dd id=\"firmware\">\u2014</dd><dt>Access point</dt><dd id=\"ap\">\u2014</dd><dt>Playback</dt><dd id=\"playback\">\u2014</dd><dt>Source readings</dt><dd id=\"freshness\">\u2014</dd></dl><a href=\"/\">Network settings</a></details>\n<footer>ONE SPEAKER. TWO DRIVERS. <span>Woofer J9 \u00b7 Tweeter J8</span></footer>\n</main></body></html>\n";
static const char cr2_web_js[] = "'use strict';\nconst $ = id => document.getElementById(id);\nlet state = null, session = null, online = false, busy = false, dragging = false;\nlet revision = 0, lastRenew = 0;\nlet music = null, musicSending = false, musicIntent = null, musicGeneration = 0;\nasync function request(path, data) {\n  const ctl = new AbortController(), timer = setTimeout(() => ctl.abort(), 3500);\n  try {\n    const response = await fetch(path, {signal: ctl.signal, cache: 'no-store',\n      ...(data ? {method: 'POST', headers: {'Content-Type':'application/json','X-CR2-Control':'1'}, body:JSON.stringify(data)} : {})});\n    if (!response.ok) throw new Error((await response.text()).slice(0,180));\n    return await response.json();\n  } finally { clearTimeout(timer); }\n}\nfunction display() {\n  $('connection').textContent = online ? 'Connected' : 'Offline';\n  $('connection').className = 'pill ' + (online ? 'online' : 'offline');\n  const active = online && state && state.armed;\n  const own = active && state.ui_active && session !== null;\n  $('power').disabled = !online || busy || (state && state.ota_active);\n  $('power').textContent = active ? 'Standby' : 'Turn on';\n  for (const id of ['volume','down','up','mute']) $(id).disabled = !own || busy;\n  displayMusic();\n  if (!state) return;\n  $('state').textContent = !online ? 'Connection lost' : state.fault ? 'Output stopped' : !active ? 'Standby' : state.control_muted ? 'Muted' : state.playing ? 'Playing' : 'Ready';\n  $('detail').textContent = !online ? 'Controls unavailable until reconnected' : state.fault ? 'Check the supply before starting again' : !active ? 'Wi-Fi stays connected' : !own ? 'Controlled by another session' : state.playing ? 'Snapcast \u00b7 woofer + tweeter' : 'Waiting for audio from Spotify';\n  if (own && !dragging) $('volume').value = state.control_volume;\n  if (online && !active) $('volume').value = 40;\n  $('level').textContent = $('volume').value;\n  $('mute').textContent = own && state.control_muted ? 'Unmute' : 'Mute';\n  const vb = state.vbus_mv;\n  $('source').textContent = !state.power_valid ? 'Unknown' : vb <= 1000 && state.vbat_mv > 13000 ? 'Battery' : state.input_selector === 1 && vb >= 18000 ? 'Pogo' : state.pd_valid ? 'USB-PD' : vb >= 4500 && vb <= 5500 ? 'USB' : 'External';\n  $('allowance').textContent = state.pd_valid ? (state.pd_mv/1000) + ' V / ' + (state.pd_ma/1000) + ' A contract' : '';\n  $('rail').textContent = state.power_valid ? (state.sys_mv/1000).toFixed(2) + ' V system' : 'Reading supply';\n  $('battery').textContent = state.power_valid && state.vbat_mv > 3000 ? (state.vbat_mv/1000).toFixed(2) + ' V' : '\u2014';\n  $('charging').textContent = state.charge ? 'Charging enabled' : 'Charging disabled';\n  $('wifi').textContent = state.rssi_dbm ? state.rssi_dbm + ' dBm' : '\u2014';\n  $('signal').textContent = !state.rssi_dbm ? 'Disconnected' : state.rssi_dbm >= -60 ? 'Strong signal' : state.rssi_dbm >= -75 ? 'Fair signal' : 'Weak signal';\n  $('firmware').textContent = state.firmware;\n  $('ap').textContent = state.bssid + ' \u00b7 channel ' + state.wifi_channel;\n  $('playback').textContent = state.resyncs + ' resyncs \u00b7 ' + state.dma_underruns + ' underruns since boot';\n  $('freshness').textContent = online && state.power_fresh ? 'Live' : 'Stale / refreshing';\n  $('volume-help').textContent = $('source').textContent === 'USB-PD' ? 'Output range follows the verified USB-PD contract.' : $('source').textContent === 'USB' ? 'Unverified USB allowance: conservative output range.' : 'Higher battery/pogo range. Increase gradually.';\n}\nasync function command(data) {\n  if (busy) return;\n  busy = true; revision++; $('message').textContent = ''; display();\n  try {\n    const result = await request('/cr2/control', data);\n    if (data.op === 'start') { session = result.session; lastRenew = Date.now(); }\n    if (data.op === 'stop') session = null;\n    online = true;\n    state = await request('/cr2/audio');\n  } catch (e) { $('message').textContent = 'Command not confirmed: ' + e.message; }\n  finally { busy = false; display(); }\n}\n$('power').onclick = () => { musicGeneration++; musicIntent = null; return command(state && state.armed ? {op:'stop'} : {op:'start',volume:Math.min(40,Number($('volume').value))}); };\n$('mute').onclick = () => command({op:'set',session,muted:!state.control_muted});\nfunction setVolume(value) {\n  const volume = Math.max(0,Math.min(100,Math.round(value)));\n  $('volume').value = volume; $('level').textContent = volume;\n  return command({op:'set',session,volume});\n}\n$('volume').onpointerdown = () => {dragging = true;};\n$('volume').oninput = () => {dragging = true; $('level').textContent = $('volume').value;};\n$('volume').onchange = () => {const value = $('volume').value; dragging = false; setVolume(value);};\n$('volume').onpointercancel = () => {dragging = false; display();};\n$('volume').onblur = () => {dragging = false;};\n$('down').onclick = () => setVolume(Number($('volume').value)-5);\n$('up').onclick = () => setVolume(Number($('volume').value)+5);\nfunction displayMusic() {\n  const pending = musicSending || !!(music && music.pending);\n  const ready = online && music && music.online && music.available;\n  const another = state && state.armed && session === null;\n  $('play').disabled = !ready || pending || busy || another;\n  $('play').textContent = pending ? 'Working\u2026' : music && music.playing ? 'Pause' : 'Play';\n  $('track').textContent = music && music.track ? music.track : 'Lose Control';\n  $('artist').textContent = !music || !music.online ? 'Music controls unavailable \u00b7 check the laptop' :\n    !music.available ? music.error || 'Spotify unavailable' : music.artist || 'Teddy Swims \u00b7 ready to play';\n}\n$('play').onclick = async () => {\n  if (musicSending || !music || music.pending) return;\n  const op = music.playing ? 'pause' : 'play';\n  const generation = ++musicGeneration;\n  musicSending = true; musicIntent = null; $('message').textContent = ''; display();\n  try {\n    music = await request('/cr2/music',{op});\n    if (generation === musicGeneration) musicIntent = {id:music.request_id,op,generation};\n  } catch(e) { $('message').textContent = 'Music command not confirmed: '+e.message; }\n  finally { musicSending = false; display(); }\n};\nasync function pollMusic() {\n  try {\n    music = await request('/cr2/music');\n    const intent = musicIntent;\n    if (intent && music.request_id === intent.id && !music.pending && !busy) {\n      musicIntent = null;\n      if (!music.succeeded) $('message').textContent = music.command_error || 'Music command failed.';\n      else if (intent.op === 'play' && music.playing) {\n        // Only completion of this tab's explicit Play click can wake the amp.\n        // A later Standby click cancels this intent; status polling never arms.\n        state = await request('/cr2/audio');\n        if (intent.generation === musicGeneration && !state.armed) await command({op:'start',volume:40});\n      }\n    }\n  } catch(e) { if(music) music.online = false; }\n  displayMusic(); setTimeout(pollMusic,1800);\n}\nasync function poll() {\n  if (!busy) {\n    const at = revision;\n    try {\n      const next = await request('/cr2/audio');\n      if (at === revision) {\n        state = next; online = true;\n        if (!state.ui_active) session = null;\n        display();\n      }\n      if (session && state.ui_active && !busy && Date.now()-lastRenew > 20000) {\n        await request('/cr2/control',{op:'renew',session}); lastRenew = Date.now();\n      }\n    } catch (e) {\n      if (at === revision) { online = false; display(); }\n    }\n  }\n  setTimeout(poll,1500);\n}\npoll();\npollMusic();\n";
static const char cr2_web_css[] = ":root{font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;color:#172e29;background:#f3f3ed;font-synthesis:none}*{box-sizing:border-box}body{margin:0}main{max-width:840px;margin:auto;padding:30px 28px 20px}header{display:flex;align-items:center;justify-content:space-between;gap:16px}.brand{color:inherit;text-decoration:none;font-size:13px;letter-spacing:2px;font-weight:750;display:flex;gap:12px;align-items:center}.brand>span:last-child{font-weight:400;color:#62716b;letter-spacing:0}.mark{font-size:31px}.pill{border:1px solid #ccd6cb;border-radius:30px;padding:7px 12px;font-size:12px;color:#52685d}.pill.online{background:#e0eddd;color:#235137}.pill.offline{background:#f8e2da;border-color:#deb9aa;color:#853f29}.hero{padding:44px 0 30px}.eyebrow{font-size:10px;font-weight:700;letter-spacing:2px;color:#708276;margin:0 0 12px}h1{font-size:clamp(34px,6vw,53px);font-weight:550;line-height:1.08;letter-spacing:-2px;margin:0}.intro{color:#63736a;font-size:15px;line-height:1.5;margin:17px 0 0}.player{background:#fff;border:1px solid #e0e5db;border-radius:22px;padding:28px 32px;box-shadow:0 10px 28px #1b392508}.player-top{display:flex;justify-content:space-between;gap:14px;align-items:center;margin-bottom:32px}.player-top .eyebrow{margin-bottom:8px}h2{margin:0;font-size:25px;font-weight:600;letter-spacing:-.6px}#detail{margin:8px 0 0;color:#6a786f;font-size:13px;min-height:16px}button{font:inherit;cursor:pointer;border:1px solid #d4ddd2;background:#f3f6f0;color:#254c39;border-radius:12px;min-height:44px;padding:10px 20px;transition:background .15s}button:hover:not(:disabled){background:#e1ebdb}button:disabled{opacity:.45;cursor:default}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #729c58;outline-offset:4px}button.power{background:#244d3b;color:white;border:0;white-space:nowrap}button.power:hover:not(:disabled){background:#34654c}.volume-head{display:flex;justify-content:space-between;align-items:center;font-size:14px;font-weight:600}output{font-size:44px;line-height:1;letter-spacing:-2px;font-weight:500;font-variant-numeric:tabular-nums}input[type=range]{width:100%;margin:25px 0 10px;accent-color:#345f40;height:28px;cursor:pointer}.scale{display:flex;justify-content:space-between;font-size:11px;color:#829080}.controls{display:flex;justify-content:center;gap:10px;margin:25px 0 18px}.controls button{min-width:50px}#mute{min-width:110px}.hint{font-size:12px;text-align:center;color:#71816f;line-height:1.6;margin:0}.message{font-size:13px;line-height:1.5;color:#9a4828;min-height:0}.message:not(:empty){padding:12px 15px;margin-top:16px;border-radius:10px;background:#fff0e8}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:18px 0 25px}.metrics article{border:1px solid #dce2d6;border-radius:16px;padding:20px}.metrics p{font-size:9px;letter-spacing:1.5px;color:#6a7e6b;margin:0 0 12px;font-weight:700}.metrics strong{display:block;font-size:23px;font-weight:550;letter-spacing:-.5px}.metrics span{display:block;font-size:11px;color:#75816e;margin-top:8px}.notes{font-size:12px;line-height:1.7;color:#6a796a}.notes strong{color:#52664f;font-weight:600}details{border-top:1px solid #dce2d6;padding:20px 0;margin-top:24px;font-size:12px;color:#65765f}summary{cursor:pointer;color:#40573c}dl{display:grid;grid-template-columns:130px 1fr;gap:10px;margin:20px 0}dd{margin:0;overflow-wrap:anywhere}details a{color:#345d40}footer{padding:14px 0 0;font-size:9px;letter-spacing:1px;color:#85907f;display:flex;justify-content:space-between;gap:15px;line-height:1.5}@media(max-width:540px){main{padding:22px 18px}.hero{padding:32px 0 24px}.player{padding:24px 22px}.metrics{gap:8px}.metrics article{padding:16px 11px}.metrics strong{font-size:18px}.metrics p{font-size:8px;letter-spacing:.8px}.metrics span{font-size:10px}footer{flex-direction:column;gap:6px}.player-top{margin-bottom:25px}button.power{padding:12px 16px}}\n\n.music{display:flex;align-items:center;justify-content:space-between;gap:18px;border-top:1px solid #e7ebe1;border-bottom:1px solid #e7ebe1;padding:20px 0;margin:-6px 0 27px}.music>div{min-width:0}.music strong{font-size:17px;font-weight:600;display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.music .eyebrow{margin-bottom:7px}.music p:last-child{font-size:12px;color:#71816f;margin:6px 0 0;line-height:1.5}.music button{min-width:90px;flex-shrink:0}\n";
